 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 */

import { COMMAND_TYPES, allowedTypes } from './machine.js';

/** Required string fields and integer-amount fields per command type. */
const FIELD_SPECS = {
  addItem: {
    required: ['sku'],
    amounts: [
      { name: 'qty', min: 1 },
      { name: 'unitPriceCents', min: 0 },
    ],
  },
  removeItem: { required: ['sku'], amounts: [] },
  pay: { required: [], amounts: [{ name: 'amountCents', min: 0 }] },
  pack: { required: [], amounts: [] },
  ship: { required: ['carrier', 'tracking'], amounts: [] },
  deliver: { required: [], amounts: [] },
  cancel: { required: ['reason'], amounts: [] },
  refund: { required: [], amounts: [{ name: 'amountCents', min: 1 }] },
};

/**
 * Validate a command's own fields, in the documented order.
 *
 * @param {string} type Command type.
 * @param {object} command Command being applied.
 * @returns {{code: string, message: string}|null} The first failure, or null.
 */
function checkFields(type, command) {
  const spec = FIELD_SPECS[type];
  for (const field of spec.required) {
    const value = command[field];
    if (typeof value !== 'string' || value === '') {
      return { code: 'MISSING_FIELD', message: `${type} requires a non-empty ${field}` };
    }
  }
  for (const { name, min } of spec.amounts) {
    const value = command[name];
    if (!Number.isInteger(value) || value < min) {
      return { code: 'BAD_AMOUNT', message: `${type} requires ${name} to be an integer >= ${min}` };
    }
  }
  return null;
}

/** An order and everything that has been asked of it. */
export class Order {
  #id;

  #state = 'created';

  #items = new Map();

  #paidCents = 0;

  #refundedCents = 0;

  #clockMs;

  #audit = [];

  #shipment = null;

  #deliveredAt = null;

  #results = new Map();

  /**
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   */
  constructor(init) {
    if (typeof init !== 'object' || init === null) throw new TypeError('init must be an object');
    if (typeof init.id !== 'string' || init.id === '') throw new TypeError('init.id must be a non-empty string');
    const createdAt = init.createdAt === undefined ? 0 : init.createdAt;
    if (!Number.isInteger(createdAt) || createdAt < 0) {
      throw new TypeError('init.createdAt must be a non-negative integer');
    }
    this.#id = init.id;
    this.#clockMs = createdAt;
  }

  /** @returns {string} Order identity. */
  get id() {
    return this.#id;
  }

  /** @returns {string} Current state. */
  get state() {
    return this.#state;
  }

  /** @returns {Array<{sku: string, qty: number, unitPriceCents: number}>} Items in ascending sku order. */
  get items() {
    return [...this.#items.keys()].sort().map((sku) => ({ ...this.#items.get(sku) }));
  }

  /** @returns {number} Sum of quantity times unit price over all items. */
  get totalCents() {
    let total = 0;
    for (const item of this.#items.values()) total += item.qty * item.unitPriceCents;
    return total;
  }

  /** @returns {number} Amount captured by a successful payment. */
  get paidCents() {
    return this.#paidCents;
  }

  /** @returns {number} Amount refunded so far. */
  get refundedCents() {
    return this.#refundedCents;
  }

  /** @returns {number} High-water mark of command timestamps. */
  get clockMs() {
    return this.#clockMs;
  }

  /** @returns {object[]} Copy of the audit trail, oldest first. */
  get audit() {
    return this.#audit.map((entry) => ({ ...entry }));
  }

  /** @returns {{carrier: string, tracking: string}|null} Shipment details once shipped. */
  get shipment() {
    return this.#shipment === null ? null : { ...this.#shipment };
  }

  /** @returns {number|null} Timestamp of delivery, once delivered. */
  get deliveredAt() {
    return this.#deliveredAt;
  }

  /** @returns {object} Plain description of the order's visible state. */
  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Run field, amount and business guards for a command that is otherwise
   * eligible to run, applying its effect when it succeeds.
   *
   * @param {object} command Command being applied.
   * @param {string} from State before the command.
   * @returns {{ok: boolean, to: string, code?: string, message?: string}} Outcome.
   */
  #evaluate(command, from) {
    const fieldError = checkFields(command.type, command);
    if (fieldError) return { ok: false, to: from, ...fieldError };

    switch (command.type) {
      case 'addItem': {
        if (this.#items.has(command.sku)) {
          return { ok: false, to: from, code: 'DUPLICATE_SKU', message: `sku ${command.sku} is already present` };
        }
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        return { ok: true, to: from };
      }
      case 'removeItem': {
        if (!this.#items.has(command.sku)) {
          return { ok: false, to: from, code: 'NO_SUCH_ITEM', message: `sku ${command.sku} is not present` };
        }
        this.#items.delete(command.sku);
        return { ok: true, to: from };
      }
      case 'pay': {
        if (this.#items.size === 0) {
          return { ok: false, to: from, code: 'EMPTY_ORDER', message: 'cannot pay an order with no items' };
        }
        if (command.amountCents !== this.totalCents) {
          return { ok: false, to: from, code: 'AMOUNT_MISMATCH', message: 'payment does not match the order total' };
        }
        this.#paidCents = command.amountCents;
        return { ok: true, to: 'paid' };
      }
      case 'pack': {
        return { ok: true, to: 'packed' };
      }
      case 'ship': {
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        return { ok: true, to: 'shipped' };
      }
      case 'deliver': {
        this.#deliveredAt = command.at;
        return { ok: true, to: 'delivered' };
      }
      case 'cancel': {
        this.#refundedCents = this.#paidCents;
        return { ok: true, to: 'cancelled' };
      }
      case 'refund': {
        const remaining = this.#paidCents - this.#refundedCents;
        if (command.amountCents > remaining) {
          return { ok: false, to: from, code: 'REFUND_TOO_LARGE', message: 'refund exceeds the amount still paid' };
        }
        this.#refundedCents += command.amountCents;
        const to = this.#refundedCents >= this.#paidCents ? 'refunded' : from;
        return { ok: true, to };
      }
      default:
        throw new TypeError(`unknown command type: ${command.type}`);
    }
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }
    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    if (this.#results.has(command.commandId)) {
      return { ...this.#results.get(command.commandId), replayed: true };
    }

    const from = this.#state;
    let auditAt;
    let outcome;

    if (command.at < this.#clockMs) {
      auditAt = this.#clockMs;
      outcome = {
        ok: false,
        to: from,
        code: 'CLOCK_REGRESSION',
        message: 'command time precedes the order clock',
      };
    } else {
      this.#clockMs = command.at;
      auditAt = command.at;
      if (!allowedTypes(from).includes(command.type)) {
        outcome = {
          ok: false,
          to: from,
          code: 'BAD_STATE',
          message: `${command.type} is not allowed while the order is ${from}`,
        };
      } else {
        outcome = this.#evaluate(command, from);
      }
    }

    const seq = this.#audit.length + 1;
    const entry = {
      seq,
      commandId: command.commandId,
      type: command.type,
      at: auditAt,
      from,
      to: outcome.to,
      ok: outcome.ok,
    };
    if (!outcome.ok) entry.code = outcome.code;
    this.#audit.push(entry);

    if (outcome.ok) this.#state = outcome.to;

    const result = outcome.ok
      ? { ok: true, state: outcome.to, seq, replayed: false }
      : { ok: false, code: outcome.code, message: outcome.message, state: outcome.to, seq, replayed: false };

    this.#results.set(command.commandId, result);
    return result;
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}
"}

